package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// SALES-REC 12 bytes
type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierEntry struct {
	TierLimit decimal.Decimal
	TierRate  decimal.Decimal
}

// Working storage
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.Zero
var WsTotal decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var TierTableArr [5]TierEntry // 1-based, 0 unused

var salesFile *os.File
var salesScanner *bufio.Scanner
var salesRec SalesRec

func isInputDone() bool { return WsEofFlag == "Y" }
func setInputDone()    { WsEofFlag = "Y" }

// helpers for storing with truncation / overflow (low-order digits)
func storeComm(v decimal.Decimal) decimal.Decimal {
	// PIC 9(6)V99 scale 2, integer 6 digits => modulus 1_000_000
	v = v.Truncate(2)
	// keep low-order digits
	modScaled := int64(100000000) // 10^(6+2)
	scaled := v.Shift(2).Truncate(0) // integer scaled
	// decimal Mod keeping sign
	// Use IntPart because range fits in int64
	si := scaled.IntPart()
	// handle negative correctly: low-order digits with sign?
	// COBOL keeps sign and low-order digits; simple mod for positive values
	// for negative, do signed mod
	sign := int64(1)
	if si < 0 {
		sign = -1
		si = -si
	}
	si = si % modScaled
	if sign < 0 {
		si = -si
	}
	return decimal.New(si, -2)
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	v = v.Truncate(2)
	modScaled := int64(100000000000) // 10^(9+2)
	si := v.Shift(2).Truncate(0).IntPart()
	sign := int64(1)
	if si < 0 {
		sign = -1
		si = -si
	}
	si = si % modScaled
	if sign < 0 {
		si = -si
	}
	return decimal.New(si, -2)
}

// numeric-edited formatting
func formatEdited(v decimal.Decimal, picture string) string {
	// picture contains Z , . 9
	// width = len(picture)
	dotIdx := strings.Index(picture, ".")
	intPic := picture
	fracPic := ""
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	}
	fracDigits := 0
	for _, ch := range fracPic {
		if ch == '9' || ch == 'Z' {
			fracDigits++
		}
	}
	capInt := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			capInt++
		}
	}
	// count integer digit slots and build
	// overflow: keep low-order integer digits
	// compute pow10 int64
	pow10 := int64(1)
	for i := 0; i < capInt; i++ {
		pow10 *= 10
	}
	absVal := v.Abs()
	// integer part modulo
	intPartVal := absVal.Truncate(0).IntPart()
	if capInt > 0 && pow10 > 1 {
		// keep low-order, handle positive only (values positive here)
		// for negative keep magnitude mod then reapply sign
		sign := int64(1)
		if intPartVal < 0 {
			sign = -1
			intPartVal = -intPartVal
		}
		intPartVal = intPartVal % pow10
		if sign < 0 {
			intPartVal = -intPartVal
		}
		if intPartVal < 0 {
			intPartVal = -intPartVal
		}
	}
	// build integer digits string zero padded to capInt
	intDigitsStr := fmt.Sprintf("%0*d", capInt, intPartVal)
	// frac part
	fracVal := int64(0)
	if fracDigits > 0 {
		// scaled = absVal * 10^fracDigits  truncated? value already has scale
		// get fractional part: (absVal - trunc) * 10^fracDigits
		// use decimal arithmetic to avoid float errors
		tenPow := decimal.NewFromInt(10).Pow(decimal.NewFromInt(int64(fracDigits)))
		scaledFrac := absVal.Mul(tenPow).Truncate(0).IntPart()
		// modulo 10^fracDigits
		modFrac := int64(1)
		for i := 0; i < fracDigits; i++ {
			modFrac *= 10
		}
		fracVal = scaledFrac % modFrac
		if fracVal < 0 {
			fracVal = -fracVal
		}
	}
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracVal)
	}

	// Build integer formatted part
	// intPic length = len(intPic)
	intFormatted := make([]byte, len(intPic))
	digitIdx := 0 // index into intDigitsStr
	// We need to map digit slots
	// Determine suppression
	// First, for each position in intPic, know if it's a digit slot
	isDigitSlot := make([]bool, len(intPic))
	isZSlot := make([]bool, len(intPic))
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			isDigitSlot[i] = true
			isZSlot[i] = (ch == 'Z')
		}
	}
	// suppression flag: true means we are still in leading zero suppression area
	suppressing := true
	// To decide, we need to know digit values in order
	// intDigitsStr corresponds to digit slots in order
	// Build slice of digits in order of slots
	digitsInOrder := []byte(intDigitsStr) // length capInt
	slotPos := 0
	for i := 0; i < len(intPic); i++ {
		if isDigitSlot[i] {
			d := digitsInOrder[slotPos]
			slotPos++
			if isZSlot[i] && suppressing && d == '0' {
				// suppressed: check if this is the last digit slot? But PIC guarantees at least one 9 at end, so last will be handled as not suppressed if it's 9
				// However for Z slots that are zero while still suppressing -> space
				intFormatted[i] = ' '
				// stay suppressing
			} else {
				// output digit
				intFormatted[i] = d
				// once we output a non-suppressed digit, suppression ends
				// But if d == '0' and slot is '9' (forced), we also end suppression
				// If d == '0' and slot is Z but we decided to output (because not suppressing), we output '0' and stay not suppressing
				suppressing = false
			}
		} else {
			// comma
			if suppressing {
				intFormatted[i] = ' '
			} else {
				intFormatted[i] = byte(intPic[i])
			}
		}
		_ = digitIdx
	}
	// Special case: if integer part is all zeros and pattern is Z...9, suppression left spaces but final 9 is '0' -> already handled: suppressing would be true until last digit (which is 9, so goes to else branch -> '0', suppressing false after)
	// Comma handling above: comma is space while suppressing, else comma.

	if dotIdx >= 0 {
		return string(intFormatted) + "." + fracStr
	}
	return string(intFormatted)
}

func formatWsCount(v int64) string {
	// PIC 9(3) zero padded to 3
	mod := int64(1000)
	v = v % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%03d", v)
}

func formatTier(v int64) string {
	// PIC 9 single digit: zero padded to 1 (same as digit)
	return fmt.Sprintf("%01d", v%10)
}

// Paragraphs

func InitPara() {
	TierTableArr[1].TierLimit = decimal.RequireFromString("1000.00")
	TierTableArr[1].TierRate = decimal.RequireFromString("2.50")
	TierTableArr[2].TierLimit = decimal.RequireFromString("5000.00")
	TierTableArr[2].TierRate = decimal.RequireFromString("4.00")
	TierTableArr[3].TierLimit = decimal.RequireFromString("20000.00")
	TierTableArr[3].TierRate = decimal.RequireFromString("5.50")
	TierTableArr[4].TierLimit = decimal.RequireFromString("999999.99")
	TierTableArr[4].TierRate = decimal.RequireFromString("7.25")
}

func ReadPara() {
	if salesScanner == nil {
		setInputDone()
		return
	}
	if !salesScanner.Scan() {
		setInputDone()
		return
	}
	line := salesScanner.Text()
	// Pad with spaces to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// Parse
	rec := SalesRec{}
	rec.SrId = line[0:4]
	field := line[4:12] // 8 chars
	trimmed := strings.TrimSpace(field)
	var dec decimal.Decimal
	if trimmed == "" {
		dec = decimal.Zero
	} else {
		// field should be digits only
		// Remove any non-digit? but assume digits
		// Parse as integer
		// If field contains spaces inside, TrimSpace already removed, but COBOL numeric field with spaces would be invalid; treat as 0
		// Use decimal New from string with shift
		// Parse integer value
		var n int64
		// field may contain leading zeros
		for _, ch := range trimmed {
			if ch >= '0' && ch <= '9' {
				n = n*10 + int64(ch-'0')
			}
		}
		dec = decimal.New(n, -2)
	}
	rec.SrSales = dec
	salesRec = rec
}

func ProcessPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		if salesRec.SrSales.Cmp(TierTableArr[WsIdx].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) /100
	rate := TierTableArr[WsTier].TierRate
	raw := salesRec.SrSales.Mul(rate).Shift(-2) // divide by 100 exact
	rounded := raw.Round(2)
	WsComm = storeComm(rounded)

	WsTotal = storeTotal(WsTotal.Add(WsComm))

	WsCount = WsCount + 1
	// overflow for count: keep low 3 digits
	WsCount = WsCount % 1000

	WsSalesEd = formatEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	tierStr := formatTier(WsTier)
	line := salesRec.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Println(line)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatWsCount(WsCount)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func main() {
	InitPara()

	var err error
	salesFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		salesFile = nil
		salesScanner = nil
		WsEofFlag = "Y"
	} else {
		defer salesFile.Close()
		salesScanner = bufio.NewScanner(salesFile)
		// allow long lines (though 12)
	}

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE SALES-FILE already deferred

	SummaryPara()
}
